const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"معدات الوقاية الشخصية (PPE)",subtitle:"Personal Protective Equipment",summary:"التعرّف على معدات الوقاية الشخصية واستخدامها الصحيح",blocks:[{body:"معدات الوقاية الشخصية (PPE) هي خط الدفاع الأخير ضد الإصابات: فقبل اللجوء إليها يجب إزالة الخطر أو تقليله بالضوابط الهندسية وإجراءات العمل (تسلسل الضوابط Hierarchy of Controls). واستخدام معدات الوقاية الشخصية في المصانع ليس اختياريًا، بل إلزامي."},{heading:"1. الأنواع الرئيسية لمعدات الوقاية الشخصية",body:"لكل جزء من الجسم معدات خاصة به:",points:["الرأس: خوذة الحماية (Hard Hat) — للحماية من سقوط الأجسام والصدمات.","العينان: نظارات السلامة (Safety Glasses) — للحماية من الغبار والمواد الكيميائية والشرر والرذاذ المتطاير.","الأذنان: واقيات السمع (Earmuffs / Earplugs) — للحماية من الضجيج العالي للآلات (85 dB(A) فأكثر).","اليدان: القفازات — للحماية من الجروح القطعية والحرارة والمواد الكيميائية.","القدمان: أحذية السلامة ذات المقدمة الفولاذية (Steel Toe) — للحماية من السحق وسقوط الأجسام الثقيلة.","الجسم: ملابس عالية الوضوح (Hi-Vis) بألوان زاهية — ليراك السائقون والعمال الآخرون."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"معدات الوقاية الشخصية (PPE)",description:"الطريقة الصحيحة لارتدائها"}],quiz:[{question:"وفقًا للمعايير الأوروبية، متى يصبح استخدام واقيات السمع إلزاميًا؟",options:[{text:"50 dB",correct:!1},{text:"70 dB",correct:!1},{text:"85 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!0},{text:"120 dB",correct:!1}],explanation:"وفقًا للتوجيه الأوروبي 2003/10/EC، عندما يبلغ متوسط مستوى الضجيج خلال 8 ساعات عمل 85 dB(A)، يجب استخدام واقيات السمع. كما تشترط OSHA عند 85 dBA تطبيق برنامج للمحافظة على السمع."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سلامة الآلات",subtitle:"Machine Safety & Guarding",summary:"حماية العمال من الأجزاء المتحركة في الآلات",blocks:[{body:"الآلات الصناعية ذات قوة كبيرة، ويمكنها في ثانية واحدة أن تسبب إصابات بالغة أو فقدان أحد أعضاء الجسم."},{heading:"1. حواجز حماية الآلات (Machine Guards)",body:"يجب توفر وسائل الحماية هذه على جميع الآلات الخطرة:",points:["الحواجز الثابتة: لتغطية السيور والتروس المتحركة.","زر إيقاف الطوارئ (E-Stop): يجب أن يكون قريبًا من يد العامل، وباللون الأحمر على خلفية صفراء.","حساسات الإيقاف: تتوقف الآلة إذا اقتربت اليد أو الجسم من المنطقة الخطرة."]},{heading:"2. القواعد الذهبية",body:"قبل العمل وفي أثنائه:",points:["لا تُزِل أبدًا حاجز الحماية عن الآلة وهي تعمل.","لا ترتدِ الملابس الفضفاضة أو السلاسل أو الخواتم، واربط الشعر الطويل، كي لا تعلق في الآلة.","إذا تعطّلت الآلة، فأوقفها فورًا بزر E-Stop، ولا تُدخل يدك في الآلة دون تطبيق إجراء عزل الطاقة وإقفالها (LOTO)."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"حواجز حماية الآلات",description:"مثال على حاجز حماية صحيح"}],quiz:[{question:"هل يجوز إزالة حاجز حماية الآلة وهي تعمل؟",options:[{text:"نعم، إذا دعت الحاجة",correct:!1},{text:"لا، لا يجوز ذلك بأي حال من الأحوال",correct:!0},{text:"فقط من أجل التنظيف",correct:!1},{text:"جميع الإجابات صحيحة",correct:!1}],explanation:"إزالة حاجز حماية الآلة وهي تعمل من أخطر السلوكيات. ولا يُجرى التنظيف والإصلاح إلا بعد إيقاف الآلة وعزل طاقتها وإقفالها (LOTO)."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"السلامة الكهربائية",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مخاطر الكهرباء ونظام الإقفال والوسم (LOTO)",blocks:[{body:"تعمل الكهرباء في المصانع بجهد عالٍ؛ ويمكن أن يؤدي الصعق الكهربائي إلى الوفاة أو إلى حروق بالغة."},{heading:"1. نظام الإقفال والوسم (Lockout/Tagout — LOTO)",body:"هذا أهم إجراء قبل إصلاح الآلات أو تنظيفها:",points:["الإقفال (Lockout): افصل مصدر الكهرباء الرئيسي وضع عليه قفلك الشخصي.","الوسم (Tagout): علّق عليه بطاقة مكتوبًا عليها: «يجري العمل عليه — لا تشغّل»، مع اسمك والتاريخ.","يجب أن يبقى المفتاح بيد الشخص الذي يجري الإصلاح فقط؛ وقبل البدء تأكّد من أن الآلة خالية فعلًا من الطاقة (Verify)."]},{heading:"2. فحص الكابلات",body:"افحص دائمًا:",points:["لا تستخدم الكابلات المقطوعة أو التي تظهر أسلاكها.","الكهرباء والماء عدوّان؛ لا تستخدم الأجهزة الكهربائية في الأماكن المبتلة."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"الإقفال والوسم (LOTO)",description:"كيف نستخدم القفل؟"}],quiz:[{question:"ما المقصود بـ LOTO؟",options:[{text:"التنظيف",correct:!1},{text:"فصل الطاقة وإقفالها قبل الإصلاح",correct:!0},{text:"زيادة سرعة الآلة",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"يُستخدم نظام LOTO كي لا يعيد أحدٌ توصيل الكهرباء بينما يعمل العامل على الآلة (OSHA 29 CFR 1910.147)."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"التعرّف على أنواع المطافئ وفئات الحريق، وشرح مفصّل لإجراء PASS",blocks:[{body:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإخماد الحرائق الصغيرة في مرحلتها الأولى. وفي المصانع يجب على كل موظف أن يعرف كيف يستخدم المطفأة بسرعة وبطريقة صحيحة. إن معرفة أنواع المطافئ وفئات الحريق ستحمي حياتك وحياة زملائك. المطفأة اليدوية لا تعمل إلا بضع ثوانٍ، لذا يجب توجيهها بشكل صحيح. وإذا كبرت النار أو كثر الدخان، فاترك المطفأة واخرج واتصل بالرقم 115."},{heading:"1. فئات الحريق وفق NFPA (Fire Classes)",body:"وفقًا للنظام الأمريكي (NFPA) تُقسم الحرائق إلى 5 فئات، وتحتاج كل فئة إلى مطفأة مناسبة. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",points:["الفئة A (المواد الصلبة): الخشب، الورق، القماش، البلاستيك. المطفأة: الماء، الرغوة، مسحوق ABC.","الفئة B (السوائل والغازات القابلة للاشتعال): البنزين، النفط الأبيض (الكيروسين)، الزيوت، الكحول، الغاز. السوائل: CO₂ أو مسحوق ABC أو الرغوة؛ وللكحول والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها. الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه. (لا تستخدم الماء أبدًا!)","الفئة C (المعدات الكهربائية الموصولة بالتيار): المفاتيح الكهربائية، المحوّلات، اللوحات الكهربائية، المولّدات. المطفأة: CO₂، مسحوق ABC، العامل النظيف (Clean Agent). (لا تستخدم الماء أو الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة الاختبار الكهربائي، كما في بعض مطافئ رذاذ الماء (water mist)!)","الفئة D (المعادن): المعادن القابلة للاشتعال — المغنيسيوم، التيتانيوم، الصوديوم، ومسحوق الألمنيوم. المطفأة: فقط مطفأة من الفئة D أو مادة يذكر ملصقها هذا المعدن؛ فالمادة تختلف من معدن لآخر. (قد يسبب الماء انفجارًا!)","الفئة K (المطابخ): زيوت الطهي والدهون. المطفأة: المادة الكيميائية الرطبة (Wet Chemical). (الماء ينثر الزيت الساخن!) — وهي الفئة F في EN 2."]},{heading:"2. أنواع المطافئ في المصانع",body:"اللون ليس فئة الحريق. وفق BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا. والفئات أدناه بأحرف NFPA:",points:["مطفأة الماء (Water): أحمر بالكامل، بلا شريط — للفئة A فقط (الخشب، الورق). لا تستخدمها أبدًا للكهرباء أو الزيت!","مطفأة CO₂: شريط أسود في بريطانيا — للفئة B وللمعدات الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). يخرج منها غاز شديد البرودة ويصبح البوق (Horn) شديد البرودة؛ أمسك المقبض فقط ولا تمسك البوق أبدًا، فقد تُصاب يدك بحروق البرد! مدى CO₂ قصير ولا تصلح لحرائق الخشب والورق العميقة: ابدأ من المسافة المحددة على ملصقها ولا تقترب إلا كلما صغرت النار. وفي الغرف الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يقلّل الأكسجين.","مطفأة مسحوق ABC (Dry Powder): شريط أزرق في بريطانيا — للفئات A وB وC (وليس D وK). وهي النوع الأكثر انتشارًا. يخرج منها مسحوق أبيض؛ ومن عيوبها أنها تحجب الرؤية وتلوّث المعدات.","مطفأة الرغوة (Foam/AFFF): شريط كريمي في بريطانيا — للفئتين A وB. تنتشر الرغوة على سطح السائل وتعزله عن الأكسجين. لا تستخدمها للكهرباء!","مطفأة العامل النظيف (Clean Agent): يختلف تصنيفها حسب الطراز، فاقرأ الملصق (غالبًا B وC بأحرف NFPA، وبعض الطرازات للفئة A أيضًا) — للمعدات الحساسة وغرف الخوادم. لا تترك بقايا ولا تُلحق ضررًا بالأجهزة الإلكترونية.","المطفأة الخاصة (Class D): للمعادن القابلة للاشتعال في المصانع — ويجب أن يذكر ملصقها المعدن المستخدم في المكان. لا ترشّ الماء أبدًا على معدن مشتعل!"]},{heading:"3. إجراء PASS — بالتفصيل",body:"قبل استخدام المطفأة، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. وPASS هي الطريقة العامة لمعظم المطافئ اليدوية؛ أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة:",points:["P = Pull (اسحب): اسحب مسمار الأمان (Safety Pin). يمنع هذا المسمار تشغيل المطفأة عن طريق الخطأ.","A = Aim (صوّب): وجّه فوهة المطفأة نحو قاعدة النار — لا نحو رأس اللهب! فوقود النار في القاعدة.","S = Squeeze (اضغط): اضغط على مقبضي المطفأة بقوة لتخرج مادة الإطفاء.","S = Sweep (حرّك): حرّك الفوهة يمينًا ويسارًا فوق قاعدة النار حتى تنطفئ تمامًا؛ ثم راقب المكان كي لا تشتعل النار من جديد."]},{heading:"4. الفحص الشهري للمطافئ",body:"الفحص البصري مرة كل شهر، يجريه الشخص المسؤول (NFPA 10):",points:["ضغط المطفأة (Pressure Gauge)، إن وُجد مؤشر: يجب أن يكون المؤشر ضمن المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.","مسمار الأمان وختمه: يجب أن يكونا في مكانهما وغير مكسورين.","الفوهة (Nozzle): يجب ألّا تكون مكسورة أو مسدودة.","جسم المطفأة: يجب ألّا يكون صدئًا أو مشقوقًا أو متضررًا.","بطاقة الفحص والملصق: يجب أن يُدوَّن على البطاقة تاريخ آخر فحص؛ وأن يكون الملصق مقروءًا ومتّجهًا إلى الخارج؛ وأن تكون المطفأة في مكانها، ظاهرة وسهلة الوصول.","ملاحظة: افصل بين هذه الأمور. الفحص والصيانة السنوية على يد فنّي مؤهَّل؛ وإعادة التعبئة (Recharge) بعد أي استخدام، ولو كان قصيرًا؛ وصيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار هيدروستاتيكي كل 12 سنة ويُفحص داخلها كل 6 سنوات؛ والاختبار الهيدروستاتيكي (Hydrostatic Test، اختبار ضغط جسم المطفأة) كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ، وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم. وموعد الاختبار ليس موعدًا للاستبدال. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك."]},{heading:"5. مخاطر خاصة في المصانع",body:"المصنع مكان حساس للأسباب الآتية:",points:["المواد الكيميائية: المذيبات، الكحول، الثنر — كلها من الفئة B.","الكهرباء ذات الجهد العالي: اللوحات الكهربائية والمحوّلات — الفئة C (NFPA).","غبار الخشب والطحين: قد يسبب انفجار الغبار (Dust Explosion) في بعض المصانع.","اللحام والقطع: يمكن أن يسبب شرر اللحام حرائق من الفئتين A وB.","مخزن الوقود: يجب أن يكون في غرفة خاصة أو خارج المبنى، وأن تكون المطفأة المناسبة (رغوة أو مسحوق) قريبة منه.","أماكن التثبيت: ضع المطافئ قرب الأبواب والممرات؛ ويجب ألّا تزيد مسافة الوصول إلى مطفأة الفئة A على 23 مترًا (75 قدمًا)، وللسوائل 9-15 مترًا (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"مطفأة الحريق في المصانع",description:"إجراء PASS وأنواع المطافئ بالفيديو"}],quiz:[{question:"بأحرف NFPA، لأيّ فئات الحريق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}],explanation:"تصلح مطفأة CO₂ للسوائل القابلة للاشتعال (B) والمعدات الكهربائية (C)، لأنها لا تترك بقايا ولا توصل الكهرباء. وفي EN 2 تعني C حرائق الغاز، ولا تُصنَّف مطفأة CO₂ لها."},{question:"في إجراء PASS، إلى أين يجب توجيه فوهة المطفأة؟",options:[{text:"رأس اللهب",correct:!1},{text:"قاعدة النار",correct:!0},{text:"بعيدًا عن النار",correct:!1},{text:"سقف الغرفة",correct:!1}],explanation:"وجّه الفوهة دائمًا نحو قاعدة النار، لأن وقود النار موجود هناك."},{question:"لماذا لا يُسكب الماء على حريق الزيت (الفئة K)؟",options:[{text:"لا يُحدث أيّ تأثير",correct:!1},{text:"الماء ينثر الزيت المشتعل ويُحدث لهبًا كبيرًا",correct:!0},{text:"الزيت يمتص الماء",correct:!1},{text:"الماء نفسه يحترق",correct:!1}],explanation:"يغلي الماء فورًا عند ملامسته الزيت الساخن ويقذف الزيت المشتعل في الهواء، فتتكوّن كرة لهب كبيرة (Fireball). استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical) أو غطاءً، واقطع مصدر الحرارة."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) والتصرّف في حالات الطوارئ في المصانع",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفرق الطبية. وخطر الإصابة في المصانع مرتفع جدًا — بدءًا من الجروح والحروق وصولًا إلى الصدمات الكهربائية والسقوط من أماكن مرتفعة. لذا يجب على كل موظف أن يعرف كيف يتصل بالإسعاف (122)، وكيف يُجري الإنعاش القلبي الرئوي (CPR)، ويوقف النزيف، ويحمي المصاب حتى وصول سيارة الإسعاف. وقد أُعدّ هذا الدرس وفق إرشادات AHA 2025 وبرنامج Stop the Bleed."},{heading:"1. الضغطات الصدرية والتنفس (CPR) — بالتفصيل",body:"الإنعاش القلبي الرئوي (CPR) إجراء لإنقاذ الحياة عندما يتوقف قلب الإنسان ويتوقف تنفّسه الطبيعي. اتبع الخطوات الآتية:",points:["1. سلامة المكان: قبل أي شيء تأكّد من أن المكان آمن (لا كهرباء ولا نار ولا غاز)، كي لا تصبح أنت الضحية الثانية.","2. الاستجابة: اهزز كتفي المصاب بقوة واسأله بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟».","3. طلب المساعدة: إذا لم يستجب وكان لا يتنفس، أو يتنفس تنفسًا غير طبيعي فقط (شهقات)، فاتصل فورًا بالرقم 122 (أو كلّف شخصًا آخر بالاتصال) واطلب إحضار جهاز إزالة الرجفان الخارجي الآلي (AED).","4. الضغطات الصدرية (Compressions): ضع كعب إحدى يديك في منتصف الصدر (النصف السفلي من عظم القص) وضع اليد الأخرى فوقها. اضغط 30 ضغطة قوية وسريعة: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة، واترك الصدر يرتدّ كاملًا.","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق الأنف وأعطِ نفَسين (مدة كل منهما نحو ثانية واحدة، حتى يرتفع الصدر). وإذا لم تستطع أو لم ترغب في إعطاء الأنفاس، فاستمر في الضغطات الصدرية فقط.","6. الاستمرار (30:2): استمر في 30 ضغطة ونفَسين حتى تصل سيارة الإسعاف، أو يصبح جهاز AED جاهزًا، أو يبدأ المصاب بالتنفس الطبيعي.","7. استخدام جهاز AED: فور وصوله شغّله، وألصق الأقطاب اللاصقة (Pads) على الصدر العاري، واتبع الأوامر الصوتية للجهاز؛ ولا تلمس المصاب في أثناء إعطاء الصدمة."]},{heading:"2. السيطرة على النزيف (Stop the Bleed)",body:"النزيف الشديد قد يقتل الإنسان في وقت قصير، لذا اتصل بالرقم 122 ونفّذ الخطوات الآتية بسرعة:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة بكلتا يديك. وإذا تشبّع القماش بالدم فلا تُزِله؛ بل ضع قطعة أخرى فوقه واستمر في الضغط.","حشو الجرح (Wound Packing): إذا كان الجرح عميقًا (كما في الفخذ أو الإبط أو الرقبة)، فاحشُ الجرح من الداخل بقماش نظيف أو بشاش مرقئ (موقف للنزيف) واضغط بقوة. لا ترفع الطرف المصاب ولا تبحث عن نقاط الضغط (Pressure Points).","العاصبة (Tourniquet): إذا كان نزيف الذراع أو الساق مهددًا للحياة، فاربط العاصبة مبكرًا وبإحكام على بعد 5-7 سم فوق الجرح (باتجاه الجسم)، وسجّل الوقت، ولا تُرخِها أبدًا.","الجسم المنغرس: إذا انغرس جسم حديدي أو زجاجي في الجرح، فلا تُخرجه أبدًا! فذلك سيزيد النزيف. اضغط حوله وثبّته."]},{heading:"3. علاج الحروق",body:"الحروق في المصانع خطيرة؛ تعامل معها على النحو الآتي، واتصل بالرقم 122 في حالة الحروق الكبيرة أو حروق الوجه واليدين:",points:["الحروق الحرارية: صبّ فورًا ماءً جاريًا باردًا (وليس ماءً مثلّجًا) على الحرق لمدة 20 دقيقة. وانزع الخواتم والساعة بسرعة قبل أن يتورّم الطرف المصاب.","الحروق الكيميائية: انزع الملابس الملوّثة واغسل الجلد بكمية كبيرة من الماء الجاري لمدة 20 دقيقة أو أكثر، وراجع صحيفة بيانات السلامة (SDS) الخاصة بالمادة.","الحروق الكهربائية: أول ما تفعله هو قطع الكهرباء! ثم برّد الحرق كما تبرّد الحرق الحراري واتصل بالرقم 122، لأن الكهرباء قد تُلحق الضرر بالقلب وبالأعضاء الداخلية.","تنبيه: لا تفقأ فقاعات الحروق، ولا تستخدم الثلج أو الزبدة والدهون أو معجون الأسنان أو المراهم دون إرشاد طبي."]},{heading:"4. الكسور وإصابات العمود الفقري",body:"عند السقوط من أماكن مرتفعة أو الاشتباه بوجود كسر:",points:["التجبير (Splinting): إذا اشتبهت بوجود كسر، فلا تحرّك الطرف المصاب. ثبّته على الوضع الذي هو عليه بقطعة خشب أو كرتون لتخفيف الألم.","حماية الظهر والرقبة: إذا سقط شخص من مكان مرتفع، فلا تحرّكه إلا إذا كان المكان خطرًا (كوجود حريق)، لأن التحريك قد يسبب الشلل. ثبّت الرأس واتصل بالرقم 122.","التبريد: لتخفيف التورّم (Swelling)، لُفّ الثلج بقطعة قماش وضعه على موضع الألم لمدة 20 دقيقة؛ ولا تضع الثلج مباشرة على الجلد."]},{heading:"5. الصعق الكهربائي والإنقاذ",body:"يمكن للكهرباء أن توقف القلب؛ نفّذ الإجراءات الآتية:",points:["اقطع الكهرباء فورًا: لا تلمس المصاب حتى تُقطع الكهرباء، لأن الكهرباء ستصعقك أنت أيضًا.","الإبعاد الآمن: إذا لم تتمكن من قطع الكهرباء وكان الجهد منخفضًا، فأبعد السلك عن المصاب بعصا خشبية جافة أو بأداة بلاستيكية، وقف على سطح جاف. ولا تقترب من خطوط الجهد العالي، واتصل بالرقم 115.","الفحص الطبي: يجب على كل من تعرّض للصعق الكهربائي، حتى لو شعر بأنه بخير، أن يذهب إلى المستشفى لفحص القلب؛ اتصل بالرقم 122."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"الإنعاش القلبي الرئوي (CPR) والإسعافات الأولية",description:"التدريب على CPR ومساعدة المصابين في المصانع"}],quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، كم يجب أن يكون معدل الضغطات الصدرية في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150+",correct:!1}],explanation:"وفقًا لإرشادات AHA 2025، يبلغ معدل الضغطات 100-120 ضغطة في الدقيقة، بعمق 5-6 سم للبالغين، كي يصل الدم إلى الدماغ."},{question:"إذا انغرس جسم حادّ في الجرح، فماذا تفعل؟",options:[{text:"أُخرجه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أُبعد يدي عنه ولا أفعل شيئًا",correct:!1},{text:"أغسله بالماء",correct:!1}],explanation:"إخراج الجسم سيزيد النزيف. يجب أن يبقى في مكانه وأن يُثبَّت حتى يُخرجه الطبيب في المستشفى."},{question:"إذا تعرّض شخص للصعق الكهربائي، فما أول ما تفعله؟",options:[{text:"أمسك يده",correct:!1},{text:"أُجري له CPR",correct:!1},{text:"أقطع الكهرباء",correct:!0},{text:"أصبّ عليه الماء",correct:!1}],explanation:"يجب أولًا قطع مصدر الكهرباء كي لا تصعقك الكهرباء أنت أيضًا؛ ثم اتصل بالرقم 122 وابدأ CPR إذا لزم الأمر."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"المواد الكيميائية (SDS)",subtitle:"Chemical Safety & Labelling",summary:"التعامل مع المواد الكيميائية والتعرّف على مخاطرها",blocks:[{body:"يمكن أن تسبب المواد الكيميائية في المصانع حروقًا جلدية أو تسممًا أو حرائق أو انفجارات."},{heading:"1. ما صحيفة بيانات السلامة (SDS)؟",body:"تقدّم صحيفة بيانات السلامة (Safety Data Sheet — SDS) معلومات كل مادة في 16 قسمًا، منها:",points:["تركيب المادة ومخاطرها.","معدات الوقاية الشخصية (PPE) المطلوبة (قناع التنفس، القفازات، النظارات).","الإسعافات الأولية في حال ملامسة المادة للجسم، وطرق إطفاء الحريق."]},{heading:"2. رموز GHS",body:"بعض العلامات الموجودة على العبوات والعلب:",points:["اللهب (Flame): مادة قابلة للاشتعال.","الجمجمة والعظمتان المتقاطعتان (Skull and Crossbones): مادة سامة قاتلة.","التآكل (Corrosion): مادة حمضية أو قلوية تُتلف الجلد والمعادن."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"صحيفة بيانات السلامة (SDS)",description:"علامات الخطر وفق GHS"}],quiz:[{question:"أين يمكننا أن نعرف نوع قناع التنفس المطلوب لمادة كيميائية؟",options:[{text:"من العلامات الموجودة على الجدار",correct:!1},{text:"في صحيفة SDS",correct:!0},{text:"أسأل زميلي",correct:!1},{text:"لا حاجة إلى قناع",correct:!1}],explanation:"تقدّم صحيفة SDS جميع معلومات الحماية الخاصة بتلك المادة، ومنها نوع معدات الوقاية الشخصية المطلوبة (القسم 8)."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"العمل في الأماكن المرتفعة",subtitle:"Fall Protection & Ladders",summary:"الوقاية من السقوط من السقالات والأسطح والسلالم",blocks:[{body:"السقوط من الأماكن المرتفعة أحد الأسباب الرئيسية للوفاة في المصانع ومواقع البناء."},{heading:"1. الحماية من السقوط",body:"يتطلب كل عمل على ارتفاع (وفق OSHA: من 1.2 متر في أماكن العمل الصناعية، ومن 1.8 متر في أعمال البناء) ما يأتي:",points:["حزام الأمان الكامل للجسم (Full Body Harness): يُرتدى بشكل صحيح ومُحكم.","حبل الأمان (Lanyard): يجب أن يكون مثبّتًا بنقطة تثبيت متينة (Anchor Point).","حواجز الحماية (Guardrails): حول السقالات والأسطح والحواف المكشوفة."]},{heading:"2. سلامة السلالم (Ladders)",body:"قاعدة نقاط التماس الثلاث:",points:["يجب أن تكون 3 من أطراف الجسم (قدمان ويد، أو يدان وقدم) على السلّم دائمًا.","يجب أن تكون زاوية وضع السلّم بنسبة 4:1 (لكل 4 أمتار من الارتفاع، تكون قاعدة السلّم على بُعد متر واحد من الجدار)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"العمل على ارتفاع",description:"استخدام حزام الأمان الكامل للجسم"}],quiz:[{question:"ما معنى قاعدة النقاط الثلاث على السلّم؟",options:[{text:"أن يقف عليه 3 أشخاص معًا",correct:!1},{text:"أن تبقى عليه 3 دقائق",correct:!1},{text:"أن تكون 3 من أطراف الجسم متصلة بالسلّم دائمًا",correct:!0},{text:"أن تربط السلّم بـ 3 حبال",correct:!1}],explanation:"تهدف قاعدة النقاط الثلاث إلى ألّا يفقد العامل توازنه فيسقط."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"الأماكن الضيقة والمحصورة",subtitle:"Confined Space Safety",summary:"العمل داخل الخزانات والأنابيب وغرف التفتيش",blocks:[{body:"الأماكن المحصورة خطرة لأن الهواء لا يتجدّد فيها، وقد ينخفض فيها الأكسجين، وتتجمّع فيها الغازات القاتلة."},{heading:"1. المخاطر الرئيسية",body:"قبل أن تدخل، اعلم ما يأتي:",points:["نقص الأكسجين (أقل من 19.5%): يؤدي إلى الاختناق.","الغازات السامة مثل CO (عديم الرائحة) وH₂S (الذي يُعطّل حاسة الشم عند التراكيز العالية).","خطر الحريق والانفجار إذا وُجدت غازات أو أبخرة قابلة للاشتعال."]},{heading:"2. إجراءات الدخول",body:"يجب توفّر الشروط الآتية:",points:["فحص الهواء بجهاز قياس الغازات (Gas Monitor) قبل الدخول وفي أثناء العمل.","وجود مراقب (Attendant) يبقى في الخارج، ويُبقي عينه على العامل في الداخل، ولا يدخل بأي حال من الأحوال.","يجب أن يكون تصريح العمل (Permit) ووسائل الاتصال وخطة الإنقاذ جاهزة."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"الأماكن المحصورة",description:"فحص الهواء"}],quiz:[{question:"هل يجوز للمراقب في الخارج أن يدخل دون معدات لإنقاذ زميله؟",options:[{text:"نعم، بدافع الإنسانية",correct:!1},{text:"لا، لأنه هو أيضًا سيختنق",correct:!0},{text:"نعم، إذا حبس أنفاسه",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"وفقًا لدراسات NIOSH، فإن جزءًا كبيرًا من الوفيات في الأماكن المحصورة هم أشخاص دخلوا للإنقاذ دون معدات أو تدريب. ويجب على المراقب أن يستدعي فريق الإنقاذ ويتصل بالرقم 115."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"الضجيج وحماية السمع",subtitle:"Hearing Conservation",summary:"الحماية من ضجيج الآلات الكبيرة",blocks:[{body:"يحدث الصمم أو ضعف السمع الناتج عن ضجيج المصانع تدريجيًا، ولا يمكن علاجه."},{heading:"1. مستويات الضجيج",body:"متى يصبح الضجيج خطرًا؟",points:["85 dB(A): حدّ بداية الخطر لمدة 8 ساعات عمل.","100 dB(A): دون حماية يكون آمنًا لمدة 15 دقيقة فقط في اليوم (NIOSH).","علامة: إذا شعرت بطنين (Tinnitus) في أذنيك بعد العمل، فهذا يعني أن الضجيج كان عاليًا جدًا."]},{heading:"2. معدات الحماية",body:"معدات حماية السمع (Hearing Protection Devices — HPD):",points:["سدادات الأذن (Earplugs): توفّر حماية جيدة إذا وُضعت بشكل صحيح.","أغطية الأذن (Earmuffs): سهلة الارتداء ومناسبة للضجيج العالي.","استخدام النوعين معًا في الأماكن شديدة الضجيج."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"الضجيج",description:"كيف تستخدم واقيات السمع؟"}],quiz:[{question:"إذا بلغ الضجيج 100 dB(A)، فكم من الوقت يمكنك البقاء دون واقيات سمع وفقًا لـ NIOSH؟",options:[{text:"ساعة واحدة",correct:!1},{text:"15 دقيقة",correct:!0},{text:"4 ساعات",correct:!1},{text:"طوال اليوم",correct:!1}],explanation:"وفقًا لـ NIOSH، كل زيادة بمقدار 3 dB تخفض الوقت الآمن إلى النصف: 85 dB(A) لمدة 8 ساعات، و100 dB(A) لمدة 15 دقيقة فقط."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"رفع الأحمال (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"الوقاية من آلام الظهر والعضلات",blocks:[{body:"إصابات الظهر من أكثر الإصابات انتشارًا في المصانع، وسببها الرفع الخاطئ للأحمال."},{heading:"1. الطريقة الصحيحة للرفع",body:"تطبيق الخطوات الآتية يحمي ظهرك:",points:["اثنِ ركبتيك: استخدم قوة ساقيك، لا قوة ظهرك.","قرّب الحمل من جسمك: كلما ابتعد الحمل عنك زاد الضغط على ظهرك.","حافظ على استقامة ظهرك: لا تحنِ ظهرك عندما ترفع شيئًا ثقيلًا.","لا تلوِ جسمك: إذا أردت نقل الحمل إلى أحد الجانبين، فاستدر بجسمك كله مستخدمًا قدميك."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"رفع الحمل",description:"الأسلوب الصحيح"}],quiz:[{question:"عند رفع شيء ثقيل، على ماذا يجب أن يقع الجهد؟",options:[{text:"الظهر",correct:!1},{text:"عضلات الساقين",correct:!0},{text:"الكتف",correct:!1},{text:"اليدان فقط",correct:!1}],explanation:"عضلات الساقين أقوى، وهي تحمي الظهر من الإصابة."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"الغازات والتهوية",subtitle:"Ventilation & Toxic Gases",summary:"التحكم في جودة الهواء والغازات السامة",blocks:[{body:"التهوية الصحيحة في المصنع مهمة لمنع تراكم الغبار والغازات التي تسبب أمراض الجهاز التنفسي."},{heading:"1. أول أكسيد الكربون (CO)",body:"الغاز القاتل الصامت:",points:["عديم اللون والرائحة.","ينتج عن احتراق الوقود وعن محركات البنزين والديزل (مثل المولّدات والرافعات الشوكية).","الأعراض: الصداع، والدوار، والغثيان، وفقدان الوعي. إذا شعرت بهذه الأعراض، فاخرج فورًا إلى الهواء الطلق واتصل بالرقم 122."]},{heading:"2. أنواع التهوية",body:"كيف يتجدّد الهواء؟",points:["التهوية الطبيعية: الأبواب والنوافذ المفتوحة.","التهوية الاصطناعية: المراوح وأنظمة الشفط الموضعي للهواء (Local Exhaust).","الوقاية الشخصية: أقنعة التنفس ذات المرشّحات وفق صحيفة SDS؛ لكن أقنعة المرشّحات لا تحمي من CO ولا من نقص الأكسجين."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"الغازات",description:"غاز أول أكسيد الكربون (CO)"}],quiz:[{question:"لماذا يُعدّ غاز CO خطرًا؟",options:[{text:"لأن رائحته كريهة",correct:!1},{text:"لأنه لا يُرى ولا يُشمّ",correct:!0},{text:"لأن لونه أحمر",correct:!1},{text:"لأنه لا يتكوّن إلا في الليل",correct:!1}],explanation:"لأنه لا يمكن الإحساس به، يتسمّم العمال دون أن يدركوا ذلك. ضع أجهزة كشف CO (CO Detector) في الأماكن التي تعمل فيها المحركات."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"الإخلاء الطارئ (Evacuation)",subtitle:"Emergency Assembly Points",summary:"خطة الخروج في أثناء الحريق أو الكارثة",blocks:[{body:"معرفة طريق الخروج قد تصنع الفرق بين الحياة والموت."},{heading:"1. قواعد الإخلاء",body:"عندما يدقّ جرس الإنذار:",points:["امشِ بهدوء وبسرعة، ولا تركض، ولا تستخدم المصعد.","أغلق الأبواب خلفك كي لا تنتشر النار والدخان، لكن لا تقفلها بالمفتاح.","توجّه إلى نقطة التجمع (Assembly Point) ليُجرى عدّ الموظفين.","لا تعد إلى الداخل بأي حال من الأحوال حتى يسمح لك مسؤول السلامة أو فرق الدفاع المدني (115)."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"تمرين الإخلاء",description:"التدريب على الإخلاء"}],quiz:[{question:"عندما يدقّ جرس الإنذار، ماذا تفعل؟",options:[{text:"جمع أغراضي",correct:!1},{text:"التوجّه بهدوء نحو المخرج",correct:!0},{text:"الاختباء تحت الطاولة",correct:!1},{text:"الصراخ",correct:!1}],explanation:"الخروج بهدوء وبسرعة هو أفضل طريقة لحماية الأرواح."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سلامة اللحام",subtitle:"Welding & Cutting Hazards",summary:"الحماية من إشعاع اللحام وحرارته ودخانه",blocks:[{body:"ينطوي اللحام على خطر الأشعة فوق البنفسجية (UV)، والحروق البالغة، والغازات والأدخنة السامة."},{heading:"1. حماية العينين والجلد",body:"متطلبات عمال اللحام:",points:["خوذة اللحام (Welding Helmet) بمرشّح مناسب: لحماية العينين من الأشعة فوق البنفسجية ومن الضوء الشديد لقوس اللحام (Arc).","قفازات جلدية طويلة: للحماية من الحرارة والشرر.","مريلة جلدية (Apron): لحماية الجسم."]},{heading:"2. خطر الحريق (Hot Work)",body:"قبل البدء احصل على تصريح العمل الساخن (Hot Work Permit)، ثم:",points:["أخلِ محيط مكان العمل من المواد القابلة للاشتعال (NFPA 51B: ضمن مسافة 11 مترًا / 35 قدمًا)، أو غطّها بستائر واقية.","جهّز مطفأة مناسبة بالقرب منك.","مراقب الحريق (Fire Watch): يبقى في المكان في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه؛ ثم يُراقَب المكان مدة تصل إلى 3 ساعات إضافية، بحسب قرار المسؤول عن التصريح (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"اللحام",description:"الارتداء الصحيح لمعدات الوقاية"}],quiz:[{question:"لماذا يبقى مراقب الحريق في المكان ساعة واحدة على الأقل بعد اللحام؟",options:[{text:"للتنظيف",correct:!1},{text:"كي لا ينشأ حريق كامن",correct:!0},{text:"لتبريد الحديد",correct:!1},{text:"لا حاجة إلى ذلك",correct:!1}],explanation:"كثيرًا ما يسقط الشرر في الشقوق وبين المواد، ويُحدث حريقًا بعد مدة. ووفقًا لـ NFPA 51B (إصدار 2019 وما بعده)، تستمر المراقبة ساعة واحدة على الأقل بعد العمل."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"معدات النقل",subtitle:"Forklift & Vehicle Safety",summary:"سلامة الرافعة الشوكية والقيادة داخل المصنع",blocks:[{body:"الرافعة الشوكية آلة ثقيلة، وتنطوي على خطر السحق والانقلاب إذا لم تُقَد بشكل صحيح."},{heading:"1. قواعد القيادة",body:"لسائقي الرافعات الشوكية:",points:["لا يقود الرافعة الشوكية إلا الأشخاص المدرَّبون والمرخَّصون (OSHA 1910.178).","لا تحمل أبدًا أي شخص على شوكتي الرافعة (Forks) أو بجانبك.","لا تحمّل الرافعة أكثر من سعتها كي لا تنقلب، واربط حزام الأمان.","خفّف السرعة عند كل زاوية أو باب، واستخدم البوق (Horn)."]},{heading:"2. سلامة المشاة",body:"إذا كنت تمشي بالقرب من رافعة شوكية:",points:["احرص على التواصل البصري مع السائق (Eye Contact) وحافظ على مسافة آمنة.","امشِ في الممرات المخصّصة للمشاة والمحدّدة بعلامات."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"الرافعة الشوكية",description:"التعرّف على النقاط العمياء (Blind Spots)"}],quiz:[{question:"إذا كان سائق الرافعة الشوكية يحمل حمولة عالية تحجب رؤيته للأمام، فماذا يفعل؟",options:[{text:"يقود بسرعة",correct:!1},{text:"يقود إلى الخلف (Reverse)",correct:!0},{text:"يستخدم البوق ويُغمض عينيه",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"عندما يحجب الحمل رؤية السائق، يجب أن يقود إلى الخلف ليرى طريقه (OSHA 1910.178)."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"علامات السلامة",subtitle:"Safety Signs & Symbols",summary:"التعرّف على ألوان السلامة ورموزها (ISO 7010)",blocks:[{body:"تنبّهنا علامات السلامة إلى المخاطر بلغة عالمية."},{heading:"1. دلالة الألوان (ISO 7010)",body:"يحمل كل لون رسالة خاصة:",points:["الأحمر: المنع أو معدات مكافحة الحريق (مثال: التدخين ممنوع).","الأصفر: التحذير والخطر (مثال: خطر الكهرباء).","الأزرق: الإلزام (مثال: يجب ارتداء خوذة الحماية).","الأخضر: السلامة والإخلاء (مثال: باب الخروج)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"علامات السلامة",description:"الرموز القياسية"}],quiz:[{question:"ما معنى العلامة ذات اللون الأصفر؟",options:[{text:"المنع",correct:!1},{text:"التحذير والخطر",correct:!0},{text:"مكان آمن",correct:!1},{text:"استخدام الماء",correct:!1}],explanation:"اللون الأصفر يعني دائمًا «انتبه» أو «يوجد خطر»."}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"النظافة والترتيب (Housekeeping)",subtitle:"Order & Maintenance",summary:"تنظيم مكان العمل لتقليل المخاطر",blocks:[{body:"مكان العمل النظيف مكان آمن. وتقع حوادث كثيرة بسبب الانزلاق أو التعثّر بالأدوات والمواد المبعثرة."},{heading:"1. القواعد العامة",body:"لجميع العمال:",points:["تنظيف الزيت أو الماء المسكوب في أسرع وقت.","جمع النفايات في حاويات خاصة.","إبقاء الممرات والمخارج مفتوحة وخالية من العوائق.","إعادة كل أداة إلى مكانها بعد انتهاء العمل."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"النظافة والترتيب",description:"مثال على مكان عمل نظيف"}],quiz:[{question:"إذا رأيت زيتًا مسكوبًا على الأرض، فماذا تفعل؟",options:[{text:"أتركه حتى يأتي عامل النظافة",correct:!1},{text:"أنظّفه أو أضع عليه علامة تحذير وأُبلغ عنه",correct:!0},{text:"أقفز فوقه",correct:!1},{text:"لا أهتم به",correct:!1}],explanation:"كل عامل مسؤول عن نظافة مكان عمله وسلامته، كي لا يسقط أحد."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"الزلزال في المصانع",subtitle:"Earthquake Safety in Factories",summary:"سلامة العمال في أثناء الزلزال وبعده",blocks:[{body:"يُشكّل الزلزال في المصانع خطرًا مضاعفًا: الاهتزاز نفسه من جهة، ومن جهة أخرى سقوط الآلات الثقيلة، وانسكاب المواد الكيميائية، وتكسّر الأنابيب، وتسرّب الغاز. لذا يجب أن تكون لكل مصنع خطة للزلازل."},{heading:"1. انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",body:"في أثناء الزلزال:",points:["انخفض إلى الأرض (Drop) وادخل تحت طاولة أو طاولة عمل (Workbench) متينة — بعيدًا عن الآلات الثقيلة والرفوف والزجاج.","إذا لم تكن هناك طاولة، فاجثُ على ركبتيك بجانب جدار داخلي وغطِّ رأسك ورقبتك بيديك (Cover).","تمسّك بالطاولة (Hold On) حتى يتوقف الاهتزاز تمامًا.","لا تركض، ولا تحتمِ تحت الآلات أو بجانب الرفوف! فالآلات الثقيلة والرفوف قد تتحرك أو تسقط عليك."]},{heading:"2. بعد الزلزال",body:"بعد توقف الاهتزاز:",points:["افحص الآلات بحثًا عن أضرار، ولا تشغّل الآلات المتضررة حتى تُفحص.","تحقّق مما إذا كانت المواد الكيميائية قد انسكبت، وابتعد عنها.","إذا شممت رائحة غاز — فاخرج بسرعة، وأخلِ المصنع، واتصل بالرقم 115 من الخارج.","لا يقطع الغازَ إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا شُمّت رائحته أو سُمع صوت تسرّب وأمكن الوصول إلى صمام الغاز بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون إحداث أيّ شرارة؛ واقطع الكهرباء إذا تضررت الأسلاك أو اللوحات الكهربائية.","قبل العودة إلى الداخل، يجب أن يفحص مهندسٌ مبنى المصنع بحثًا عن تشققات."]},{heading:"3. الاستعداد",body:"الخطة المسبقة:",points:["أعدّ خطة للزلازل لكل قسم.","ثبّت الآلات الثقيلة بالسلاسل أو البراغي.","ضع البراميل وعبوات المواد الكيميائية على رفوف منخفضة وثابتة.","أبقِ ممرات الإخلاء مفتوحة دائمًا.","أجرِ تمرينًا مرة كل 6 أشهر."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"الزلزال",description:"الزلزال في المصنع"}],quiz:[{question:"في أثناء الزلزال في المصنع، ما أول ما تفعله؟",options:[{text:"الركض نحو الخارج",correct:!1},{text:"الانخفاض إلى الأرض والدخول تحت طاولة متينة",correct:!0},{text:"إطفاء الآلات",correct:!1},{text:"الاقتراب من النوافذ",correct:!1}],explanation:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On) — هذا هو الإجراء الأول داخل المباني، بعيدًا عن الآلات والرفوف والزجاج."},{question:"بعد الزلزال في مصنع للمواد الكيميائية، ما أول ما يجب فحصه؟",options:[{text:"الكهرباء",correct:!1},{text:"انسكاب المواد الكيميائية",correct:!0},{text:"الماء",correct:!1},{text:"الهاتف",correct:!1}],explanation:"انسكاب المواد الكيميائية خطر كبير بعد الزلزال، ويجب فحصه بسرعة."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"السيول والفيضانات",subtitle:"Flood Emergency in Industrial Areas",summary:"حماية المصانع والعمال في أثناء السيول",blocks:[{body:"يمكن للسيول أن تدمّر المصانع تدميرًا كاملًا: فهي تُتلف الآلات، وتنشر المواد الكيميائية، وتجعل الكهرباء مصدر خطر. والمصانع القريبة من الأنهار والوديان أكثر عرضة للخطر."},{heading:"1. قبل السيل",body:"الاستعداد:",points:["تابع تحذيرات الأرصاد الجوية (Meteorology).","انقل المعدات المهمة والمواد الكيميائية إلى مكان مرتفع.","جهّز نظام الكهرباء للفصل التلقائي (Auto-shutoff).","ضع أكياس الرمل (Sandbags) أمام الأبواب وعند أساسات المصنع."]},{heading:"2. في أثناء السيل",body:"الإجراءات العاجلة:",points:["إذا استطعت ذلك بأمان ولم تصل المياه إلى اللوحات الكهربائية، فاقطع الكهرباء والغاز؛ ولا تلمس الكهرباء وأنت في الماء!","لا تدخل مياه السيل — فـ 15 سم من الماء المتدفق بسرعة يمكن أن تُسقط الإنسان، و30 سم يمكن أن تجرف السيارة.","انتقل إلى مكان مرتفع — الطابق الثاني أو السطح.","اتصل بالرقم 115 وابقَ في مكانك حتى تصل فرق الإنقاذ."]},{heading:"3. بعد السيل",body:"العودة والتنظيف:",points:["لا تدخل المصنع حتى يتأكد مهندس من أن المبنى آمن.","لا تلمس المواد الكيميائية التي وصلت إليها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115.","لا تُعِد تشغيل الكهرباء حتى يفحص كهربائي مختص النظام.","التقط صورًا لجميع الأضرار من أجل التأمين والتقرير."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"السيول",description:"السيول في المصنع"}],quiz:[{question:"في أثناء السيل في المصنع، ما أول ما تفعله؟",options:[{text:"احمِ الآلات",correct:!1},{text:"اقطع الكهرباء والغاز إذا استطعت ذلك بأمان",correct:!0},{text:"اذهب إلى البيت",correct:!1},{text:"اسحب الماء إلى الخارج بالمضخة",correct:!1}],explanation:"الكهرباء والغاز هما الخطران الأولان في أثناء السيل؛ لكن إذا وصلت المياه إلى اللوحات الكهربائية، فلا تقترب منها وانتقل إلى مكان مرتفع."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"استجابة الدفاع المدني في المصانع",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"تشكيل فريق الاستجابة في المصنع عند وقوع الحوادث، والتنسيق مع الدفاع المدني (115)",blocks:[{body:"يجب أن تمتلك المصانع الكبيرة (النفط، والغاز، والكيمياويات، والصلب) فرقًا خاصة بها للاستجابة للطوارئ تعمل قبل وصول فرق الدفاع المدني (115). ويحدّد معيار NFPA 600 (Facility Fire Brigades) تنظيم فرق الإطفاء في المنشآت الصناعية وتدريبها ومعداتها. والدقائق الأولى من الحادث بالغة الأهمية، لذا يجب أن يكون فريق المصنع جاهزًا ومدرَّبًا."},{heading:"1. تشكيل فريق الاستجابة للطوارئ في المصنع (ERT)",body:"المبادئ الأساسية لفريق الاستجابة للطوارئ (Emergency Response Team):",points:["حجم الفريق: يُحدَّد بناءً على تقييم مخاطر المصنع ومهام الفريق؛ ولا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين.","التدريب: بحسب مهام كل عضو، مع تدريب تنشيطي (Refresher) مرة واحدة في السنة على الأقل.","قائد الحادث (Incident Commander — IC): شخص واحد فقط يُصدر الأوامر، كي لا تتضارب الأوامر.","المهام الرئيسية: إطفاء الحريق، والإنقاذ، والإسعافات الأولية، وإخلاء المبنى.","الاتصال: أجهزة لاسلكي (Radio) على قناة مخصّصة، والهاتف المحمول وسيلةً احتياطية.","زمن الاستجابة: حدّده في الخطة، وقِسه بالتمارين، وحسّنه.","توصية: دورتا ICS-100 وICS-200 (FEMA) لتعلّم نظام قيادة الحوادث."]},{heading:"2. خطة الاستجابة للطوارئ (ERP)",body:"خطة الاستجابة للطوارئ (Emergency Response Plan) وفق المعايير:",points:["يجب أن تكون خطة الطوارئ مكتوبة ومتاحة في المصنع؛ ويجوز للمنشآت التي يعمل فيها 10 موظفين أو أقل إبلاغها شفهيًا (OSHA 29 CFR 1910.38).","الأقسام الرئيسية: المهام، والإجراءات، وطرق الإخلاء، والاتصالات، والموارد، والتمارين، والتقييم بعد الحادث.","نقاط التجمع (Assembly Points): نقطة رئيسية وأخرى احتياطية، في مكان آمن بعيد عن المبنى وعن طريق مركبات الطوارئ.","طرق الإخلاء: طريقان على الأقل من كل طابق بوجه عام (NFPA 101، مع بعض الاستثناءات).","إنذار الحريق (Alarm): يجب أن يُسمع أو يُرى في جميع أنحاء المبنى (NFPA 72).","فريق الإسعافات الأولية: يجب أن يوجد في كل وردية (Shift) موظفون تلقّوا تدريبًا على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR).","التمارين (Drill): تُجرى بانتظام، وتُسجَّل نتائج كل تمرين.","التقييم بعد الحادث (Post-Response Critique): في أقرب وقت ممكن بعد كل حادث."]},{heading:"3. التنسيق مع الدفاع المدني (115)",body:"عند وقوع الحادث ووصول فرق الدفاع المدني (115)، يجب على فريق ERT اتباع الخطوات الآتية:",points:["1. اتصل فورًا بالرقم 115، وبالرقم 122 إذا كان هناك مصابون.","2. قدّم المعلومات الأساسية: الموقع، ونوع الحادث، وعدد المصابين، والمواد الخطرة، وطريق الوصول.","3. جهّز خريطة المصنع (Site Map) عند البوابة، مع مواقع الخطر وأماكن قطع الكهرباء والغاز.","4. ضابط الاتصال (Liaison Officer): شخص واحد فقط يتواصل مع الدفاع المدني (115).","5. جهّز صحائف بيانات السلامة (SDS) لجميع المواد الكيميائية.","6. سجّل أسماء الشهود وإفاداتهم.","7. نقل القيادة: عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة.","8. التوثيق: الصور والفيديو وسجلّ الحادث (Incident Log) لأغراض التحقيق والتأمين."]},{heading:"4. العمل مع فريق المواد الخطرة (HazMat)",body:"في الحوادث الكيميائية، يلزم فريق HazMat:",points:["مستويات التدريب على المواد الخطرة (OSHA 1910.120 وNFPA 470، الذي دُمج فيه NFPA 472):","• مستوى التوعية (Awareness): التعرّف على الخطر، والابتعاد، والإبلاغ — لجميع الموظفين.","• مستوى العمليات (Operations): حماية الناس والمحيط بأساليب دفاعية (Defensive) من مسافة بعيدة.","• مستوى الفني (Technician): إيقاف التسرّب من مسافة قريبة (Offensive) بمعدات وقاية شخصية خاصة.","• مستوى الأخصائي (Specialist): معرفة متعمّقة بمواد محدّدة ودعم الفنيين.","ثلاث مناطق: المنطقة الساخنة (Hot Zone)، والمنطقة الدافئة (Warm Zone)، والمنطقة الباردة (Cold Zone).","مستويات معدات الوقاية الشخصية في HazMat: A، B، C، D (المستوى A أعلى درجات الحماية).","تُجرى إزالة التلوث (Decontamination) في المنطقة الدافئة، قبل الانتقال إلى المنطقة الباردة.","لا يدخل الموظفون غير المدرَّبين المنطقة الساخنة؛ بل ينتظرون فرق الدفاع المدني (115).","يجب أن تحدّد خطة المصنع كيفية طلب الفرق المتخصّصة بالمواد الخطرة عبر الرقم 115."]},{heading:"5. الاستجابة المشتركة لعدة جهات (Multi-Agency Response)",body:"تتطلب الحوادث الكبيرة مشاركة عدة جهات:",points:["115 الدفاع المدني: إطفاء الحريق، والإنقاذ، والمواد الخطرة.","122 الإسعاف: العلاج الطبي ونقل المصابين.","104 الشرطة: تطويق المنطقة، وتنظيم المرور، والتحقيق القانوني.","الأجهزة الأمنية: عند الاشتباه بوجود متفجرات أو عمل إرهابي — ويجري إبلاغها عبر الرقم 104.","وزارة الصحة: تجهيز المستشفيات القريبة.","مديرية الكهرباء: قطع الكهرباء عن المنطقة المحيطة.","دوائر الماء والغاز: قطع خطوط الماء والغاز.","هيئة البيئة: إذا انتشرت المواد الكيميائية في البيئة.","مركز عمليات الطوارئ (EOC): للحوادث الكبيرة التي تشارك فيها جهات عديدة."]},{heading:"6. مراحل الاستجابة (5 مراحل)",body:"يمرّ كل حادث بالمراحل الخمس الآتية:",points:["1. الاكتشاف (Detection): الحساسات، أو إنذار الحريق، أو الشهود.","2. الإبلاغ (Notification): الاتصال بالرقم 115، وإبلاغ فريق ERT وضابط الاتصال.","3. الاستجابة (Response): يعمل فريق ERT حتى تصل فرق الدفاع المدني (115).","4. تخفيف الخطر (Mitigation): إطفاء الحريق، والإنقاذ، وإزالة التلوث.","5. التعافي (Recovery): التنظيف، والتحليل، والتقييم بعد الحادث.","يجب توثيق كل مرحلة (خطة عمل الحادث Incident Action Plan — IAP).","الساعة الذهبية (Golden Hour): العلاج السريع بعد الإصابة البالغة يزيد فرص النجاة — لذا فإن الاتصال السريع بالرقم 122 أمر مهم."]},{heading:"7. التمارين والتدريب (Drills & Training)",body:"التمارين أساس الاستعداد (الجدول المقترح):",points:["تمرين المحاكاة المكتبية (Tabletop Exercise): مرة كل 3 أشهر — سيناريو يُناقش حول الطاولة.","التمرين الوظيفي (Functional Drill): مرة كل 6 أشهر — لفريق ERT فقط، لا للمبنى كله.","التمرين الشامل (Full-Scale Drill): مرة في السنة — للمصنع كله بالاشتراك مع الدفاع المدني (115).","التقييم: تقرير ما بعد التمرين (After-Action Report) في أقرب وقت ممكن.","تدريب فريق ERT: بصورة مستمرة وبحسب المهام، ومرة واحدة في السنة على الأقل.","معايير الكفاءة: NFPA 1081 (Facility Fire Brigade Member)، وOSHA 1910 Subpart L، وICS-100/200.","تمرين مشترك مع الدفاع المدني (115): مرة في السنة لأغراض التنسيق."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"تمرين الاستجابة لفريق ERT",description:"تمرين شامل في مصنع نفط"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"هيكل نظام قيادة الحوادث (ICS)",description:"هيكل نظام قيادة الحوادث (ICS)"}],quiz:[{question:"كيف يُحدَّد حجم فريق الاستجابة للطوارئ (ERT) في المصنع؟",options:[{text:"بنسبة ثابتة: 1 لكل 100 موظف",correct:!1},{text:"بناءً على تقييم مخاطر المصنع ومهام الفريق",correct:!0},{text:"بنسبة ثابتة: 1 لكل 200 موظف",correct:!1},{text:"بنسبة ثابتة: 1 لكل 25 موظفًا",correct:!1}],explanation:"لا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين؛ بل يحدّد كل مصنع حجم فريقه بحسب مخاطره ومهامه."},{question:"ما معنى الساعة الذهبية (Golden Hour)؟",options:[{text:"ساعة عمل خاصة",correct:!1},{text:"الوقت الأول بعد الإصابة البالغة، الذي يكون فيه العلاج السريع بالغ الأهمية",correct:!0},{text:"وقت الظهيرة",correct:!1},{text:"حرارة النهار",correct:!1}],explanation:"الساعة الذهبية (Golden Hour) هي الفترة التي تلي الإصابة البالغة، والتي يزيد فيها الإيصال السريع للمصاب إلى العلاج من فرص نجاته؛ لذا اتصل فورًا بالرقم 122."},{question:"في نظام ICS، ما عمل ضابط الاتصال (Liaison Officer)؟",options:[{text:"يُطفئ الحريق",correct:!1},{text:"يتواصل مع الجهات الخارجية",correct:!0},{text:"يُجري CPR",correct:!1},{text:"يُغلق الباب",correct:!1}],explanation:"يتواصل ضابط الاتصال مع الدفاع المدني (115)، والشرطة (104)، والإسعاف (122)، والجهات الأخرى."},{question:"ما عمل مستوى العمليات (Operations) في HazMat؟",options:[{text:"الإبلاغ فقط",correct:!1},{text:"دفاعي (Defensive) — منع الانتشار من مسافة بعيدة",correct:!0},{text:"هجومي (Offensive) — إيقاف التسرّب من مسافة قريبة",correct:!1},{text:"التخصّص (Specialist)",correct:!1}],explanation:"مستوى العمليات (Operations) دفاعي (Defensive): منع انتشار المادة من مسافة بعيدة، وليس العمل عن قرب (Offensive)."},{question:"ما المنطقة الساخنة (Hot Zone) في HazMat؟",options:[{text:"مكان بارد وآمن",correct:!1},{text:"منطقة نظيفة تمامًا",correct:!1},{text:"المنطقة الأشد خطرًا — لا يدخلها إلا فنيو HazMat بمعدات الوقاية الشخصية المناسبة",correct:!0},{text:"منطقة التجمع",correct:!1}],explanation:"المنطقة الساخنة هي موقع المادة الخطرة؛ ولا يدخلها إلا فنيو HazMat بمعدات وقاية شخصية من المستوى A أو B."},{question:"عندما تصل فرق الدفاع المدني (115) إلى موقع الحادث، إلى من تنتقل القيادة؟",options:[{text:"يستمر فريق ERT في القيادة",correct:!1},{text:"قائد فرق الدفاع المدني (115)",correct:!0},{text:"مدير المصنع",correct:!1},{text:"الشرطة",correct:!1}],explanation:"نقل القيادة (ICS Transfer): عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"تصنيف الحرائق في المصانع",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"تصنيف خاص بالمصانع: السوائل، والغازات، والمعادن، والغبار القابل للاشتعال",blocks:[{body:"تستخدم هذه الوحدة نظام NFPA: A المواد الصلبة، B السوائل والغازات القابلة للاشتعال، C المعدات الكهربائية، D المعادن، K زيت الطهي. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. والمعايير الخاصة بالمصانع هي: السوائل القابلة للاشتعال (NFPA 30)، والمعادن القابلة للاشتعال (NFPA 484)، والغبار القابل للاشتعال (NFPA 654). ومنذ إصدار 2025، دُمج NFPA 484 وNFPA 654 في المعيار NFPA 660."},{heading:"1. الفئة A — المواد الصلبة القابلة للاشتعال في المصنع",body:"المواد الصلبة الشائعة في المصانع:",points:["الوقود: الورق، والكرتون، والقماش، والخشب، والمطاط، والبلاستيك، والمنصّات النقالة (Pallets).","تخلّف هذه المواد جمرًا ونارًا كامنة؛ لذا برّد المكان بالماء بعد الإطفاء وراقبه.","في المصانع: تنشر مخازن الورق والكرتون والمنصّات الخشبية النار بسرعة.","المطفأة: الماء، الرغوة، مسحوق ABC.","المنصّات الفارغة المكدّسة خطر كبير: لا تكدّسها عاليًا، وخزّنها في الخارج أو في مكان مزوّد بالمرشّات (Sprinklers).","المعيار: NFPA 13 (أنظمة المرشّات)، الذي يشمل حماية المخازن أيضًا.","أمثلة في المصانع: المخازن وخطوط التعبئة والتغليف (Packaging Lines)."]},{heading:"2. الفئة B — السوائل القابلة للاشتعال في المصنع",body:"إحدى أخطر الفئات في المصانع:",points:["الوقود: البنزين، والنفط الأبيض (الكيروسين)، والديزل، والأسيتون (Acetone)، والتولوين (Toluene)، والزايلين (Xylene).","نقطة الوميض (Flash Point): البنزين نحو -43°C، والأسيتون -20°C، والديزل 52°C أو أكثر.","حدود الانفجار (LEL/UEL): أدنى تركيز وأعلى تركيز للبخار في الهواء يمكن أن يشتعل:","• البنزين: 1.4-7.6%.","• الأسيتون: 2.5-12.8%.","• الميثانول (Methanol): 6-36%.","المطفأة: الرغوة (AFFF أو الرغوة الخالية من الفلور)، CO₂، مسحوق ABC. وللأسيتون والميثانول والكحولات والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها.","لا ترشّ نفثة ماء مباشرة على السائل — فهي تنشر النار. ويحدث BLEVE (Boiling Liquid Expanding Vapor Explosion) عندما يسخن خزان مضغوط بفعل النار.","فئات السوائل وفق NFPA 30 (Flash Point = نقطة الوميض، Boiling Point = نقطة الغليان):","• الفئة I (سوائل قابلة للاشتعال – Flammable): نقطة الوميض أقل من 37.8°C — IA (الوميض < 22.8°C والغليان < 37.8°C)، IB (الوميض < 22.8°C والغليان 37.8°C أو أكثر)، IC (الوميض من 22.8 إلى < 37.8°C).","• الفئة II (سوائل قابلة للاحتراق – Combustible): نقطة الوميض من 37.8 إلى < 60°C.","• الفئة III (سوائل قابلة للاحتراق – Combustible): IIIA من 60 إلى < 93°C، وIIIB 93°C أو أكثر.","جدران الاحتواء (Diking): وفق NFPA 30، يجب ألّا تقل سعة منطقة الاحتواء عن كمية السائل التي يمكن أن تنسكب من أكبر خزان ممتلئ (100%)؛ أما نسبة 110% فتشترطها بعض القوانين والإرشادات الأخرى (لاستيعاب مياه الأمطار أيضًا).","كثافة البخار (Vapor Density): بخار البنزين أثقل من الهواء (نحو 3-4 مرات) ويتجمّع في الأماكن المنخفضة."]},{heading:"3. الغازات القابلة للاشتعال — NFPA: الفئة B، EN 2: الفئة C",body:"غازات المصانع: الأسيتيلين، والبروبان، والهيدروجين:",points:["المصادر: الأسيتيلين (Acetylene) للحام، والبروبان (Propane) لبعض الرافعات الشوكية، والهيدروجين (Hydrogen) الناتج عن شحن بطاريات الرصاص الحمضية (Lead-acid).","هذه المواد غازية في درجات الحرارة العادية وتشتعل بسهولة. حدود الانفجار في الهواء: الهيدروجين 4-75%، والبروبان 2.1-9.5%، والأسيتيلين من 2.5% فأكثر. (-253°C هي نقطة غليان الهيدروجين، وليست نقطة وميضه.)","تتجاوز حرارة لهب الأكسي-أسيتيلين (Oxy-Acetylene) 3000°C.","يُكوّن الأسيتيلين مع النحاس (Copper) مادة متفجرة (Copper Acetylide)؛ لا تستخدم أنابيب ومعدات نحاسية غير مناسبة.","الإطفاء: أولًا، أغلق صمام الغاز إذا كان ذلك آمنًا. ولا تُطفئ نار الغاز إذا لم تستطع إيقاف تدفقه — فالغاز المتسرّب قد يُحدث انفجارًا.","تستخدم فرق الدفاع المدني (115) رذاذ الماء (Water Spray) من بعيد لتبريد الأسطوانات والخزانات، لا لإطفاء لهب الغاز.","أجهزة كشف الغاز (Gas Detectors) في مخازن الغاز: يجب أن يعمل الإنذار قبل بلوغ LEL بفارق كبير (عادةً عند 10-20% من LEL).","في المصانع: أماكن اللحام، وأماكن شحن الرافعات الشوكية، وغرف البطاريات."]},{heading:"4. الفئة D — المعادن القابلة للاشتعال (NFPA 484)",body:"المعادن القابلة للاشتعال — من أخطر الأنواع:",points:["الوقود: المغنيسيوم، والتيتانيوم، ومسحوق الألمنيوم، والصوديوم، والليثيوم المعدني (Lithium Metal).","تحترق هذه المعادن بحرارة عالية جدًا وتُصدر ضوءًا شديدًا جدًا؛ لا تنظر مباشرة إلى اللهب.","الماء ممنوع! Mg + H₂O → MgO + H₂ (يتكوّن الهيدروجين وقد ينفجر).","CO₂ ممنوع! 2Mg + CO₂ → 2MgO + C (المغنيسيوم يحترق حتى في CO₂).","مطافئ الفئة D فقط، وفقط التي يذكر ملصقها هذا المعدن: فالمادة تختلف من معدن لآخر (مثل مسحوق قائم على كلوريد الصوديوم (NaCl) أو الغرافيت؛ ومسحوق النحاس لليثيوم). ولا تستخدم الماء أو المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا.","أمثلة في المصانع: صهر الألمنيوم، وخراطة المغنيسيوم، وبطاريات الليثيوم المعدني.","NFPA 484: تخزين المعادن القابلة للاشتعال ومناولتها وحمايتها (أصبح الآن جزءًا من NFPA 660).","مسحوق الألمنيوم: ينطوي أيضًا على خطر انفجار الغبار (NFPA 654 / 660).","الاستجابة: اتصل فورًا بالرقم 115 ولا تستخدم إلا مطفأة الفئة D التي يذكر ملصقها هذا المعدن. أما بطاريات الليثيوم أيون (Li-ion) فلا تحتوي على ليثيوم معدني، وتُبرَّد بالماء."]},{heading:"5. الغبار القابل للاشتعال — انفجار الغبار (NFPA 654)",body:"خطر قاتل في المصانع:",points:["خماسي الغبار (Dust Pentagon): الوقود (الغبار) + الأكسجين + الحرارة + الانتشار في الهواء + الحيّز المغلق.","المصادر: الطحين، والسكر، والخشب، والفحم، وغبار المعادن، والبلاستيك.","تختلف أدنى درجة حرارة للاشتعال (MIT) باختلاف نوع الغبار؛ راجع صحيفة SDS أو نتائج اختبار الغبار.","ويختلف كذلك أدنى تركيز للانفجار (MEC) باختلاف نوع الغبار؛ والغبار المنتشر في الهواء خطِر دائمًا.","الانفجار الأولي (Primary): داخل جهاز ما (مثل المرشّح أو المطحنة).","الانفجار الثانوي (Secondary): يُثير الانفجار الأولي الغبار المتراكم على الأرض والرفوف والأنابيب، فيحدث انفجار أكبر وأشد فتكًا.","تقليل الخطر: أنظمة تجميع الغبار، وفتحات تنفيس الانفجار (Explosion Vents)، وأنظمة الإخماد.","النظافة: قد تُشكّل طبقة من الغبار بسماكة 0.8 مم (1/32 inch) على أكثر من 5% من مساحة الأرضية خطرًا (NFPA 654 / OSHA).","مثال: في عام 2008، في مصنع السكر Imperial Sugar (الولايات المتحدة)، أودى انفجار غبار السكر بحياة 14 عاملًا (CSB).","المعايير: NFPA 654 (الآن NFPA 660) وOSHA 29 CFR 1910.272 (لمخازن الحبوب)."]},{heading:"6. مراحل تطوّر الحريق في المصنع",body:"4 مراحل قياسية — وقد تكون النار في المصانع أسرع:",points:["البداية (Incipient): نار صغيرة — يمكن لشخص مدرَّب إطفاؤها بالمطفأة اليدوية المناسبة بعد إطلاق الإنذار والاتصال بالرقم 115، وطريق الخروج خلفه؛ وإذا لم تنطفئ فورًا، فاخرج.","النمو (Growth): تزداد النار والدخان بسرعة وتعمل المرشّات — اخرج واتصل بالرقم 115.","الاشتعال الكامل (Fully Developed): بعد الاشتعال الوميضي (Flashover) — لفرق الدفاع المدني (115) فقط.","الخمود (Decay): يقلّ الوقود، لكن خطر الارتداد اللهبي (Backdraft) والانهيار يبقى قائمًا.","في المصانع، يمكن للمخازن المرتفعة والمنصّات النقالة والسوائل أن توصل النار إلى مرحلة الاشتعال الكامل أسرع مما يحدث في المنازل.","خزانات الغاز والسوائل المضغوطة إذا سخنت بفعل النار قد تنفجر بظاهرة BLEVE — أخلِ المنطقة المحيطة بسرعة.","يجب أن تُبقي خطة المصنع طريق وصول فرق الدفاع المدني (115) ومآخذ مياه الإطفاء (Hydrants) جاهزة ومفتوحة.","مراقب الحريق بعد العمل الساخن (Hot Work): في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه، ثم المراقبة مدة تصل إلى 3 ساعات إضافية بحسب قرار المسؤول عن التصريح (NFPA 51B)."]},{heading:"7. الحمل الحريقي (Fire Load) وتقييم المخاطر",body:"فحص المخاطر في المصنع:",points:["كثافة الحمل الحريقي (Fire Load Density — MJ/m²): كمية الطاقة التي يمكن أن تطلقها المواد القابلة للاشتعال في كل متر مربع. المتوسطات وفق EN 1991-1-2 (Eurocode 1):","• المساكن (Dwelling): نحو 780 MJ/m².","• المكاتب (Office): نحو 420 MJ/m².","• المكتبات (Library): نحو 1500 MJ/m².","• المخازن والمصانع: يُحسب بحسب المواد المخزّنة، وكثيرًا ما يكون أعلى من هذه القيم.","تقييم المخاطر (Risk Assessment): الخطر = احتمال الحدوث (Likelihood) × شدّة العواقب (Severity).","• منخفض (Low): يُسيطر عليه بالإجراءات المعتادة.","• متوسط (Medium): يحتاج إلى ضوابط إضافية ومراقبة.","• مرتفع (High): يتطلب إجراءً عاجلًا قبل مواصلة العمل.","• مرتفع جدًا (Extreme): يتوقف العمل حتى ينخفض الخطر.","تُحدَّد مقاومة الجدران والأسقف للحريق (Fire Resistance Rating) بحسب نوع المبنى واستخدامه وفق أكواد البناء (مثل NFPA 101 وNFPA 5000).","حدّث تقييم مخاطر المصنع (مثل HVA) مرة واحدة في السنة على الأقل، وبعد كل تغيير كبير."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"انفجار الغبار",description:"عرض توضيحي لانفجار الغبار"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"جدول فئات الحريق",description:"تصنيف الحرائق في المصانع"}],quiz:[{question:"لحريق من الفئة D، أيّ مطفأة تكون مناسبة؟",options:[{text:"مسحوق ABC",correct:!1},{text:"الماء",correct:!1},{text:"مطفأة الفئة D التي يذكر ملصقها هذا المعدن",correct:!0},{text:"CO₂",correct:!1}],explanation:"لا تصلح إلا مطفأة من الفئة D أو مادة يذكر ملصقها المعدن المشتعل؛ فالمادة تختلف من معدن لآخر. لا تستخدم الماء أو CO₂ أو مسحوق ABC."},{question:"ما معنى BLEVE؟",options:[{text:"إنذار الحريق",correct:!1},{text:"انفجار البخار المتمدّد للسائل المغلي (Boiling Liquid Expanding Vapor Explosion)",correct:!0},{text:"نظام المرشّات",correct:!1},{text:"فئة الغاز",correct:!1}],explanation:"BLEVE هو انفجار خزان سائل مضغوط عندما يسخن بفعل النار فيتمدّد البخار بسرعة."},{question:"كم عنصرًا في خماسي الغبار (Dust Pentagon)؟",options:[{text:"3",correct:!1},{text:"4",correct:!1},{text:"5",correct:!0},{text:"6",correct:!1}],explanation:"خمسة عناصر: الوقود + الأكسجين + الحرارة + الانتشار + الحيّز المغلق."},{question:"ماذا يُكوّن الأسيتيلين مع النحاس (Copper)؟",options:[{text:"لا يحدث شيء",correct:!1},{text:"أسيتيليد النحاس (Copper Acetylide) — مادة متفجرة",correct:!0},{text:"التنظيف",correct:!1},{text:"حرارة منخفضة",correct:!1}],explanation:"يُكوّن الأسيتيلين مع النحاس مادة متفجرة حساسة (Copper Acetylide) تنفجر بالصدم أو بالحرارة."},{question:"ما الخطر الذي ينطوي عليه مسحوق الألمنيوم (Aluminum Powder)؟",options:[{text:"الفئة A فقط",correct:!1},{text:"الفئة D وانفجار الغبار",correct:!0},{text:"الغاز فقط",correct:!1},{text:"لا خطر فيه",correct:!1}],explanation:"مسحوق الألمنيوم معدن قابل للاشتعال (الفئة D) وغبار قابل للاشتعال في آن واحد (NFPA 484 / 654، الآن NFPA 660)."},{question:"وفقًا لـ EN 1991-1-2، كم يبلغ متوسط الحمل الحريقي في المساكن (Dwelling) تقريبًا؟",options:[{text:"100 MJ/m²",correct:!1},{text:"230 MJ/m²",correct:!1},{text:"420 MJ/m²",correct:!1},{text:"780 MJ/m²",correct:!0}],explanation:"يبلغ متوسط الحمل الحريقي في المساكن نحو 780 MJ/m²، وفي المكاتب نحو 420 MJ/m² (EN 1991-1-2، الجدول E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"أنظمة إطفاء الحريق في المصانع",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"المطافئ اليدوية وأنظمة إطفاء الحريق الثابتة في المصانع",blocks:[{body:"تحتاج المصانع إلى مستويين من إطفاء الحريق: 1) المطافئ اليدوية (Portable Extinguishers) للحرائق الصغيرة في مرحلتها الأولى، 2) أنظمة الإطفاء الثابتة (Fixed Suppression Systems) للحماية المستمرة. وبحسب نوع الخطر: المرشّات (NFPA 13)، والرغوة (NFPA 11 / 16)، وCO₂ (NFPA 12)، والمسحوق الجاف (NFPA 17)، والعامل النظيف (Clean Agent — NFPA 2001). وتشرح هذه الوحدة هذه الأنظمة وجدول الفحص."},{heading:"1. المطافئ اليدوية — الاختيار في المصنع",body:"7 أنواع رئيسية وجدول الاختيار:",points:["مسحوق ABC (Multi-purpose): النوع الأكثر انتشارًا للممرات والأماكن العامة — A، B، C (وليس D وK).","CO₂: للوحات الكهربائية وغرف الخوادم — B، C.","الرغوة (AFFF / Foam): لمخازن السوائل ومناطق جدران الاحتواء — A، B.","المادة الكيميائية الرطبة (Wet Chemical): لمطبخ المصنع ومقصفه — K.","العامل النظيف (Clean Agent): لغرف الخوادم وغرف التحكم.","الفئة D (مادة يذكر ملصقها المعدن المستخدم في المكان): لخراطة المعادن وصهر الألمنيوم.","الرذاذ المائي Water Mist (قطيرات دقيقة من ماء منزوع المعادن): للفئة A، وبعض الطرازات للفئة C — بحسب اعتماد الجهاز (Listing).","مستويات الخطر وفق NFPA 10 (الحد الأدنى لتصنيف مطفأة الفئة A):","• خطر منخفض (Light Hazard — المكاتب): 2-A.","• خطر عادي (Ordinary Hazard — المصنع العادي): 2-A.","• خطر مرتفع (Extra Hazard — مصنع فيه كميات كبيرة من المواد القابلة للاشتعال): 4-A.","مسافة الوصول (Travel Distance) إلى المطفأة:","• الفئة A: حتى 23 مترًا (75 قدمًا) في جميع المستويات.","• الفئة B: 9 أو 15 مترًا (30 / 50 قدمًا) بحسب تصنيف المطفأة ومستوى الخطر."]},{heading:"2. أنظمة المرشّات — NFPA 13",body:"أهم نظام ثابت في كثير من المصانع:",points:["4 أنواع من أنظمة المرشّات:","• الأنابيب الرطبة (Wet Pipe): الأنابيب مملوءة بالماء دائمًا — أسرع استجابة والنوع الأكثر انتشارًا.","• الأنابيب الجافة (Dry Pipe): الأنابيب مملوءة بالهواء أو النيتروجين المضغوط — للأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C.","• التفعيل المسبق (Pre-action): لا يُفتح الصمام إلا بعد اكتشاف الحريق بالكواشف، ثم يُفتح رأس المرشّ بالحرارة — للأماكن التي تحتوي على معدات حساسة.","• الغمر (Deluge): رؤوس مفتوحة ترشّ جميعها الماء معًا — للأماكن عالية الخطورة.","درجة حرارة التشغيل (Activation Temperature) ولون الأمبولة الزجاجية:","• 57°C (برتقالي): الدرجة العادية (Ordinary) — الأماكن ذات الحرارة المنخفضة.","• 68°C (أحمر): الدرجة العادية (Ordinary) — الأكثر انتشارًا في المكاتب والمصانع.","• 79°C (أصفر) و93°C (أخضر): الدرجة المتوسطة (Intermediate) — الأماكن الأكثر حرارة.","• 141°C (أزرق): الدرجة العالية (High) — غرف المراجل وقرب المعدات الساخنة.","مساحة الحماية لكل رأس عادي (Standard Spray): حتى نحو 21 m² (Light)، و12 m² (Ordinary)، و9 m² (Extra Hazard).","كثافة التصريف (Density): 0.10-0.40 gpm/ft² (نحو 4-16 mm/min) بحسب مستوى الخطر.","NFPA 25: الفحص والاختبار وفق جداول أسبوعية وشهرية وسنوية وكل 5 سنوات.","لا تُفتح المرشّات إلا في موضع الحريق؛ ولا تُفتح جميع الرؤوس معًا (باستثناء نظام الغمر Deluge)."]},{heading:"3. أنظمة الرغوة — NFPA 11 / 16",body:"لمخازن السوائل الكبيرة:",points:["3 أنواع من الرغوة بحسب نسبة التمدّد (Expansion):","• منخفضة (Low-Expansion، حتى 20:1): حرائق الخزانات وانسكاب السوائل.","• متوسطة (Medium-Expansion، من 20:1 إلى 200:1): مناطق جدران الاحتواء.","• عالية (High-Expansion، من 200:1 إلى 1000:1): حظائر الطائرات والأماكن المغلقة الكبيرة.","أنواع مركّز الرغوة (Concentrate):","• AFFF: للهيدروكربونات (البنزين، الديزل).","• AR-AFFF (Alcohol-Resistant): للمذيبات القطبية (الكحول، الأسيتون).","• Fluoroprotein: لخزانات التخزين.","• الرغوة الخالية من الفلور (Fluorine-Free Foam — F3): بديل رغوات PFAS.","معدّل التطبيق (Application Rate):","• انسكاب الهيدروكربونات: لا يقل عن نحو 4.1 L/min/m² (0.10 gpm/ft²).","• المذيبات القطبية: بحسب اعتماد الشركة المصنّعة، وهو أعلى عمومًا.","خطر PFAS: تحتوي AFFF على مواد فلورية (PFAS) تتراكم في الجسم والبيئة؛ وتتجه دول كثيرة نحو الرغوة الخالية من الفلور (F3).","في المصانع: مجمّعات الخزانات، وأماكن تحميل الصهاريج، ومصافي النفط."]},{heading:"4. أنظمة CO₂ والعامل النظيف (Clean Agent) — NFPA 12 / 2001",body:"لغرف المعدات والغمر الكلي (Total Flooding):",points:["الغمر الكلي بـ CO₂:","• تركيز التصميم: 34% على الأقل (NFPA 12)، وأكثر لبعض المواد.","• الخطر: تركيز الإطفاء قاتل للبشر — يجب ألّا يبقى أحد في الغرفة.","• إنذار ما قبل التصريف وزمن التأخير (Time Delay): يجب أن يكون كافيًا لإخلاء الغرفة قبل إطلاق الغاز (NFPA 12).","• الاستخدام: غرف المولّدات، وأماكن اختبار المحركات، ومعدات الطباعة.","العامل النظيف (Clean Agent) — FK-5-1-12 / HFC-227ea:","• NOAEL: في الأماكن المشغولة بالأشخاص، لا يتجاوز تركيز التصميم مستوى عدم ظهور أي أثر ضار (NOAEL) (NFPA 2001)؛ ومع ذلك أخلِ الغرفة.","• تركيز التصميم: عادةً نحو 4-9% بحسب نوع المادة.","• التصريف (Discharge): خلال 10 ثوانٍ للمواد الهالوكربونية (NFPA 2001).","• الاستخدام: غرف الخوادم، وغرف التحكم، وغرف لوحات التوزيع الكهربائية.","• تكلفتها أعلى بكثير من أنظمة الماء.","الهالون Halon 1301: أُوقف إنتاجه في الدول المتقدمة منذ 1994 بموجب بروتوكول مونتريال، لأنه يدمّر طبقة الأوزون؛ ولا تُركَّب به أنظمة جديدة.","الاختبار الهيدروستاتيكي للمطافئ اليدوية (NFPA 10): CO₂ كل 5 سنوات، والعامل النظيف كل 12 سنة؛ أما أسطوانات الأنظمة الثابتة فتخضع لـ NFPA 12 / 2001 ولأنظمة الأسطوانات."]},{heading:"5. أنظمة المسحوق الجاف — NFPA 17",body:"للمخاطر الخاصة:",points:["الأنظمة مسبقة التصميم (Pre-Engineered Systems):","• المطابخ التجارية: تُستخدم فيها الآن عمومًا أنظمة المادة الكيميائية الرطبة (Wet Chemical) وفق NFPA 17A، لا المسحوق الجاف.","• غرف الطلاء بالرش (Spray Booths).","• حماية المعدات والمركبات الثقيلة.","• خزانات الغمس (Dip Tanks).","المواد (Agents):","• بيكربونات الصوديوم (Sodium Bicarbonate): B، C.","• بيكربونات البوتاسيوم (Purple-K): B، C — أقوى من بيكربونات الصوديوم على حرائق الفئة B.","• فوسفات أحادي الأمونيوم (Monoammonium Phosphate): A، B، C.","• كلوريد البوتاسيوم (Potassium Chloride): B، C.","التشغيل (Activation): كاشف حرارة أو مقبض تشغيل يدوي (Manual Pull).","بعد التصريف: ينتشر المسحوق في كل مكان وقد يُتلف الأجهزة الإلكترونية؛ والتنظيف صعب.","تُحدَّد مساحة الحماية لكل فوهة (Nozzle) بحسب اعتماد النظام (Listing)."]},{heading:"6. كشف الحريق — NFPA 72",body:"نظام الكشف — خط الإنذار الأول:",points:["أنواع الكواشف:","• الدخان: الكهروضوئي (Photoelectric) للحرائق البطيئة المكتومة (Smoldering)، والتأيّني (Ionization) للحرائق ذات اللهب (Flaming).","• الحرارة: درجة ثابتة (Fixed Temperature، مثل 57°C) أو الارتفاع السريع (Rate-of-Rise).","• اللهب (Flame): UV/IR — تكشف اللهب بسرعة.","• الغاز: كواشف LEL وحساسات CO.","• سحب عينات الهواء (Air-Sampling): لغرف الخوادم — النوع الأكثر حساسية.","المسافات والمساحات:","• الدخان: المسافة بين الكواشف نحو 9 أمتار (30 ft) على السقف المستوي (NFPA 72).","• الحرارة: بحسب المسافة المعتمدة للكاشف (Listed Spacing).","• اللهب: بحسب زاوية الرؤية والمسافة المعتمدة للجهاز.","الإنذار (Alarm Notification):","• الصوتي (Audible): أعلى عمومًا بـ 15 dB على الأقل من متوسط الضجيج في المكان (NFPA 72).","• الضوئي (Strobe): للأماكن الصاخبة ولذوي الإعاقة السمعية.","• الإنذار الصوتي الناطق (Voice / Mass Notification): للمباني والمصانع الكبيرة.","الفحص والاختبار: وفق جداول NFPA 72 (تُختبر أجهزة كثيرة مرة في السنة)."]},{heading:"7. جدول الفحص والصيانة",body:"وفق معايير NFPA:",points:["يوميًا / أسبوعيًا:","• الفحص البصري (قراءة مقاييس الضغط، والأضرار).","• التأكّد من عدم وجود عوائق أمام المرشّات.","• تشغيل مضخة الحريق دون تدفق الماء (No-flow Test): مضخة الديزل كل أسبوع، والكهربائية عمومًا كل شهر (NFPA 25).","شهريًا:","• الفحص البصري للمطافئ اليدوية (NFPA 10).","• فحص لوحة إنذار الحريق وإشارات الأعطال (Trouble).","• فحص أزرار الإنذار اليدوية (Manual Pull Stations) — ظاهرة وغير محجوبة.","سنويًا:","• الصيانة السنوية للمطافئ اليدوية على يد شخص مختص (وهي ليست الاختبار الهيدروستاتيكي).","• فحص المرشّات من مستوى الأرض (NFPA 25).","• أخذ عينة من مركّز الرغوة لاختبارها.","• اختبار الكواشف وأجهزة الإنذار (NFPA 72).","كل بضع سنوات:","• الاختبار الهيدروستاتيكي للمطافئ (اختبار ضغط جسم المطفأة، NFPA 10): كل 5 سنوات للماء والرغوة والمادة الكيميائية الرطبة (Wet Chemical) وCO₂ والمسحوق الجاف ذي الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة للمسحوق الجاف ذي الضغط المخزَّن (stored-pressure) الذي جسمه من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم، وللعامل النظيف (Clean Agent). وبشكل منفصل، كل 6 سنوات تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن التي تحتاج إلى اختبار كل 12 سنة ويُفحص داخلها على يد شخص مختص. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.","• الفحص الداخلي لأنابيب المرشّات: كل 5 سنوات (NFPA 25).","• استبدال رؤوس المرشّات أو اختبار عينات منها بعد 50 سنة (الرؤوس العادية — NFPA 25).","التسجيل: دوّن جميع عمليات الفحص والاختبار، واحفظ السجلات وفق المعايير ومتطلبات الجهات المختصة."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"تشغيل المرشّ",description:"عرض توضيحي لعمل المرشّ"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"جدول أنظمة الإطفاء",description:"الأنظمة الثابتة"}],quiz:[{question:"ما أهم نظام ثابت في معظم المصانع؟",options:[{text:"المطافئ اليدوية",correct:!1},{text:"المرشّات (NFPA 13)",correct:!0},{text:"CO₂ فقط",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"تعمل المرشّات تلقائيًا وتسيطر على الحريق في مرحلته الأولى، حتى عند عدم وجود أحد في المكان؛ أما المطافئ اليدوية فهي للحرائق الصغيرة فقط."},{question:"لأيّ مكان لا يصلح نظام الأنابيب الرطبة (Wet Pipe)؟",options:[{text:"غرف المعدات (ICT)",correct:!1},{text:"المكاتب",correct:!1},{text:"الأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C",correct:!0},{text:"المخازن",correct:!1}],explanation:"في الأماكن الباردة يتجمّد الماء في الأنابيب؛ ونظام الأنابيب الجافة (Dry Pipe) هو المناسب."},{question:"هل تُركَّب أنظمة جديدة تعمل بالهالون Halon 1301؟",options:[{text:"نعم",correct:!1},{text:"لا — أُوقف إنتاجه بموجب بروتوكول مونتريال",correct:!0},{text:"في غرف ICT فقط",correct:!1},{text:"في غرف الخوادم فقط",correct:!1}],explanation:"يدمّر Halon 1301 طبقة الأوزون؛ وقد أُوقف إنتاجه في الدول المتقدمة منذ 1994."},{question:"لماذا يجب أن يخرج الجميع من الغرفة قبل تصريف نظام الغمر الكلي بـ CO₂؟",options:[{text:"لا داعي لذلك، فـ CO₂ غير ضار",correct:!1},{text:"لأن تركيز الإطفاء (34% فأكثر) قاتل للبشر",correct:!0},{text:"لأن CO₂ يرشّ الماء",correct:!1},{text:"لأن CO₂ يُحدث صوتًا عاليًا",correct:!1}],explanation:"يبلغ تركيز تصميم CO₂ في أنظمة الغمر الكلي 34% على الأقل (NFPA 12)، وهذا التركيز يُفقد الإنسان وعيه ويقتله خلال وقت قصير؛ ولهذا يوجد إنذار ما قبل التصريف وزمن التأخير."},{question:"كم تبلغ مساحة الحماية لكل رأس مرشّ (Standard Spray) تقريبًا؟",options:[{text:"2-5 m²",correct:!1},{text:"12-21 m²",correct:!0},{text:"50 m²",correct:!1},{text:"100 m²",correct:!1}],explanation:"وفق NFPA 13: نحو 21 m² للخطر المنخفض، و12 m² للخطر العادي؛ وأقل من ذلك للخطر المرتفع (نحو 9 m²)."},{question:"ما الاختبار الأسبوعي لمضخة الحريق الديزل؟",options:[{text:"الفحص البصري فقط",correct:!1},{text:"تشغيل المضخة دون تدفق الماء (Start / No-flow Test)",correct:!0},{text:"الاختبار الهيدروستاتيكي",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"وفق NFPA 25: تُشغَّل مضخة الديزل كل أسبوع، والمضخة الكهربائية عمومًا كل شهر، وتُختبر دون تدفق الماء."}]}],t={lessons:e};export{t as default,e as lessons};
